<?php $page_title='Lab Test';require_once __DIR__.'/../includes/header.php';$p=$pdo->query("SELECT id,name FROM patients ORDER BY name")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare("INSERT INTO lab_tests(patient_id,test_date,test_name,result,status,notes) VALUES(?,?,?,?,?,?)")->execute([$_POST['patient_id'],$_POST['test_date'],$_POST['test_name'],$_POST['result'],$_POST['status'],$_POST['notes']]);header('Location:index.php');exit;}?><h2>Add Lab Test</h2><div class="card p-4 mt-3"><form method="post"><div class="row g-3"><div class="col-md-6"><label>Patient</label><select name="patient_id" class="form-select"><?php foreach($p as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><label>Date</label><input type="date" name="test_date" value="<?=date('Y-m-d')?>" class="form-control"></div><div class="col-md-6"><label>Test Name</label><input name="test_name" class="form-control" required></div><div class="col-md-6"><label>Status</label><select name="status" class="form-select"><option>pending</option><option>completed</option></select></div><div class="col-12"><label>Result</label><textarea name="result" class="form-control"></textarea></div><div class="col-12"><label>Notes</label><textarea name="notes" class="form-control"></textarea></div></div><button class="btn btn-primary mt-3">Save Lab Test</button></form></div><?php require_once __DIR__.'/../includes/footer.php';?>